<canvas id="canvas"></canvas><div class="hud">MODE <b id="h-mode">SNOW</b><br>DEPTH <b id="h-depth">4</b><br>ANGLE <b id="h-angle">60</b><br><span class="sub">SEGMENTS</span> <b id="h-seg">0</b></div><?php $interactionHints=[['type'=>'click','label'=>'pulse'],['type'=>'drag','label'=>'bend']];require_once __DIR__ . '/includes/interaction-hints.php';?>
<div id="controls" class="drawer-controls"><div><div class="btn-row"><button class="control-btn active" data-mode="snow">SNOW</button><button class="control-btn" data-mode="curve">CURVE</button><button class="control-btn" data-mode="island">ISLAND</button></div></div><div><div class="slider-row"><span class="slider-label">DEPTH</span><input type="range" id="sl-depth" min="0" max="6" value="4"><span class="slider-value" id="sv-depth">4</span></div></div><div><div class="slider-row"><span class="slider-label">ANGLE</span><input type="range" id="sl-angle" min="35" max="85" value="60"><span class="slider-value" id="sv-angle">60</span></div></div><div><div class="btn-row"><button class="control-btn active" id="btn-draw">DRAW</button><button class="control-btn" id="btn-reset">RESET</button></div></div></div><?php require_once __DIR__ . '/includes/drawer-controls.php';?>
<script>(function(){var c=document.getElementById('canvas'),x=c.getContext('2d'),W,H,D=1,mode='snow',depth=4,angle=60,phase=1,auto=true,pulses=[];var hm=document.getElementById('h-mode'),hd=document.getElementById('h-depth'),ha=document.getElementById('h-angle'),hs=document.getElementById('h-seg'),sd=document.getElementById('sl-depth'),sa=document.getElementById('sl-angle'),vd=document.getElementById('sv-depth'),va=document.getElementById('sv-angle');function resize(){D=Math.min(2,devicePixelRatio||1);W=c.width=Math.floor(innerWidth*D);H=c.height=Math.floor(innerHeight*D);c.style.width=innerWidth+'px';c.style.height=innerHeight+'px'}function build(a,b,n,out){if(n<=0){out.push([a,b]);return}var dx=(b.x-a.x)/3,dy=(b.y-a.y)/3,p1={x:a.x+dx,y:a.y+dy},p3={x:a.x+dx*2,y:a.y+dy*2},th=-angle*Math.PI/180,px=p1.x+dx*Math.cos(th)-dy*Math.sin(th),py=p1.y+dx*Math.sin(th)+dy*Math.cos(th),p2={x:px,y:py};build(a,p1,n-1,out);build(p1,p2,n-1,out);build(p2,p3,n-1,out);build(p3,b,n-1,out)}function pts(){var r=Math.min(W,H)*.32,cx=W/2,cy=H/2,out=[];if(mode==='curve'){build({x:cx-r*1.4,y:cy+r*.25},{x:cx+r*1.4,y:cy+r*.25},depth,out)}else{var sides=mode==='island'?5:3,base=[];for(var i=0;i<sides;i++){var a=-Math.PI/2+i*Math.PI*2/sides;base.push({x:cx+Math.cos(a)*r,y:cy+Math.sin(a)*r})}for(var j=0;j<sides;j++)build(base[j],base[(j+1)%sides],depth,out)}return out}function draw(){if(auto)phase=Math.min(1,phase+.018);x.fillStyle='rgba(10,10,15,.2)';x.fillRect(0,0,W,H);var p=pts(),lim=Math.max(1,Math.floor(p.length*phase));x.globalCompositeOperation='lighter';for(var i=0;i<lim;i++){var a=p[i][0],b=p[i][1],q=i/p.length;x.strokeStyle=i%2?'rgba(123,44,191,'+(.18+q*.45)+')':'rgba(0,245,212,'+(.2+q*.55)+')';x.lineWidth=(1.1+q*1.2)*D;x.beginPath();x.moveTo(a.x,a.y);x.lineTo(b.x,b.y);x.stroke()}for(var k=pulses.length-1;k>=0;k--){var o=pulses[k];o.l+=.025;x.strokeStyle='rgba(0,245,212,'+Math.max(0,.65-o.l)+')';x.beginPath();x.arc(o.x*D,o.y*D,o.l*180*D,0,Math.PI*2);x.stroke();if(o.l>1)pulses.splice(k,1)}x.globalCompositeOperation='source-over';hs.textContent=p.length;requestAnimationFrame(draw)}function hud(){hm.textContent=mode.toUpperCase();hd.textContent=depth;vd.textContent=depth;ha.textContent=angle;va.textContent=angle;phase=.02}c.onpointerdown=e=>{pulses.push({x:e.clientX,y:e.clientY,l:0});if(typeof SFX!=='undefined')SFX.play('ripple',100)};c.onpointermove=e=>{if(e.buttons){angle=Math.max(35,Math.min(85,angle+(e.movementX||0)*.08));sa.value=Math.round(angle);hud();if(typeof SFX!=='undefined')SFX.play('move',120)}};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(q=>q.classList.toggle('active',q===b));hud();if(typeof SFX!=='undefined')SFX.play('toggle')});sd.oninput=()=>{depth=+sd.value;hud()};sa.oninput=()=>{angle=+sa.value;hud()};document.getElementById('btn-draw').onclick=e=>{auto=!auto;e.currentTarget.classList.toggle('active',auto);if(typeof SFX!=='undefined')SFX.play('toggle')};document.getElementById('btn-reset').onclick=()=>{phase=.02;if(typeof SFX!=='undefined')SFX.play('success')};addEventListener('resize',resize);resize();hud();draw()})();</script><?php require_once __DIR__ . '/includes/sfx.php';require_once __DIR__ . '/includes/page-end.php';?></body></html>